#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>
#include <XPT2046_Touchscreen.h>

// CYD display pins
#define TFT_CS 15
#define TFT_DC 2
#define TFT_RST -1
#define TFT_BL 21

// Touchscreen pins
#define TOUCH_CS 33
#define TOUCH_IRQ 36

Adafruit_ILI9341 tft(TFT_CS, TFT_DC, TFT_RST);

SPIClass touchSPI(HSPI);
XPT2046_Touchscreen touch(TOUCH_CS, TOUCH_IRQ);

#define WHITE ILI9341_WHITE

uint16_t colors[] = {
  ILI9341_BLACK,
  ILI9341_RED,
  ILI9341_BLUE,
  ILI9341_GREEN,
  ILI9341_YELLOW,
  ILI9341_MAGENTA,
  ILI9341_CYAN,
  ILI9341_ORANGE
};

int selectedColor = 1;
int brushSize = 3;
bool eraser = false;

int lastX = -1;
int lastY = -1;

void toolbar() {
  tft.fillRect(0, 0, 320, 65, ILI9341_DARKGREY);

  for (int i = 0; i < 8; i++) {
    tft.fillRect(i * 40 + 5, 5, 30, 25, colors[i]);
    if (i == selectedColor)
      tft.drawRect(i * 40 + 3, 3, 34, 29, WHITE);
  }

  tft.setTextSize(1);
  tft.setTextColor(WHITE);

  tft.drawRect(5, 39, 48, 22, WHITE);
  tft.drawString("Small", 12, 46);

  tft.drawRect(60, 39, 60, 22, WHITE);
  tft.drawString("Medium", 72, 46);

  tft.drawRect(125, 39, 55, 22, WHITE);
  tft.drawString("Large", 140, 46);

  tft.drawRect(190, 39, 55, 22, WHITE);
  tft.drawString("Eraser", 198, 46);

  tft.drawRect(255, 39, 58, 22, WHITE);
  tft.drawString("Clear", 265, 46);
}

void setup() {
  Serial.begin(115200);

  pinMode(TFT_BL, OUTPUT);
  digitalWrite(TFT_BL, HIGH);

  SPI.begin(14, 12, 13, TFT_CS);
  tft.begin();
  tft.setRotation(1);
  tft.fillScreen(WHITE);

  touchSPI.begin(25, 39, 32, TOUCH_CS);
  touch.begin(touchSPI);
  touch.setRotation(1);

  toolbar();

  tft.fillRect(0, 65, 320, 175, WHITE);
}

void loop() {
  if (!touch.touched()) {
    lastX = -1;
    lastY = -1;
    return;
  }

  TS_Point p = touch.getPoint();

  int x = map(p.y, 200, 3700, 0, 320);
  int y = map(p.x, 200, 3700, 240, 0);

  x = constrain(x, 0, 319);
  y = constrain(y, 0, 239);

  if (y < 35) {
    selectedColor = x / 40;
    eraser = false;
    toolbar();
    lastX = -1;
    return;
  }

  if (y < 65) {
    if (x < 55) brushSize = 2;
    else if (x < 125) brushSize = 4;
    else if (x < 185) brushSize = 8;
    else if (x < 250) eraser = true;
    else {
      tft.fillRect(0, 65, 320, 175, WHITE);
    }

    lastX = -1;
    return;
  }

  uint16_t color = eraser ? WHITE : colors[selectedColor];

  if (lastX == -1) {
    tft.fillCircle(x, y, brushSize, color);
  } else {
    tft.drawLine(lastX, lastY, x, y, color);
    tft.fillCircle(x, y, brushSize, color);
  }

  lastX = x;
  lastY = y;
}
